// Package tipstate relates a local ref to what the RSL records for it.
//
// A local ref matches the RSL tip, is behind it at an earlier recorded tip or
// inside a recorded push, is ahead of it with commits the RSL never recorded,
// or has diverged. The relation only states facts about the RSL record: it
// says nothing about whether that record verifies.
package tipstate

import (
	"context"
	"errors"
	"fmt"

	"github.com/entireio/entire-rsl/internal/rslread"
	"github.com/entireio/entire-rsl/internal/store"
	"github.com/gittuf/gittuf/pkg/githash"
)

// Kinds of relation.
const (
	Match  = "match"
	Behind = "behind"
	Ahead  = "ahead"
	// Revoked is a commit only a skipped entry's push brought in, even if a
	// later unskipped entry still contains it.
	Revoked  = "revoked"
	Diverged = "diverged"
	// TooFar is a commit behind the tip whose push is further back than the
	// search covers, so its coverage could not be established.
	TooFar = "too_far"
)

// maxCoverSearch caps the entries searched for the push that introduced a
// commit behind the tip.
const maxCoverSearch = 1000

// ErrNoEntries is returned when the RSL holds no unskipped entry for the ref.
var ErrNoEntries = errors.New("the RSL has no unskipped entry for the ref")

// ErrTipMissing is returned when the object the RSL tip records is not in the
// local repository and the local ref is not at an earlier recorded tip, so
// the two cannot be compared.
var ErrTipMissing = errors.New("the object the RSL tip records is not in the local repository")

// Relation is how a local tip relates to the RSL record of its ref.
type Relation struct {
	// Entry is, for Behind, the unskipped entry that recorded the local tip,
	// or the push that introduced it.
	Entry *rslread.Target
	// Tip is the newest unskipped entry, which records the RSL tip.
	Tip  rslread.Target
	Kind string
	// Exact is set for Behind when Entry records exactly the local tip.
	Exact bool
	// EntriesBehind counts, for Behind, the unskipped entries newer than
	// Entry.
	EntriesBehind int
	// Commits counts the commits between the local tip and the RSL tip: the
	// local ref lacks them for Behind, the RSL lacks them for Ahead.
	Commits int
	// TipMissing is set for Behind when the object the RSL tip records is
	// not in the local repository, so Commits could not be counted.
	TipMissing bool
}

// Relate compares local with the entries for ref. Errors reading the
// repository are returned, never read as a relation.
func Relate(ctx context.Context, st *store.Store, reader *rslread.Reader, ref string, local githash.Hash) (Relation, error) {
	all, err := reader.Targets(ctx, ref)
	if err != nil {
		return Relation{}, err
	}

	var unskipped, skipped []rslread.Target
	for _, t := range all {
		if t.Skipped {
			skipped = append(skipped, t)
		} else {
			unskipped = append(unskipped, t)
		}

package testutil

import (
	"testing"

	"github.com/gittuf/gittuf/pkg/githash"
	"github.com/gittuf/gittuf/pkg/rsl"
)

// Fixture checkpoint IDs. CheckpointULID's shard is "7Z" and CheckpointHex's
// is "f7", the last two characters of each.
const (
	CheckpointULID = "01JC0FFEE0BADC0DE00000007Z"
	CheckpointHex  = "a3b2c4d5e6f7"
	RepositoryID   = "01J9ZREPQ0000000000000000R"
	PusherJane     = "01J9ZACCT000000000000000JD (jane)"
	PusherBob      = "01J9ZACCT000000000000000BB (bob)"
)

// Scenario is a repository shaped like one Entire's server records: a root
// of trust authorizing the cluster key, branches, a moved tag, checkpoint refs,
// a rogue entry and a revoked one.
type Scenario struct {
	*Repo

	MainFirst, MainSecond         githash.Hash // commits on main
	MainFirstEntry, MainLastEntry githash.Hash // RSL entries for main
	TrailerCommit                 githash.Hash // main tip, carries Entire-Checkpoint
	FeatureEntry                  githash.Hash // recorded by the mirror service
	TagFirstEntry, TagMovedEntry  githash.Hash // v1.0.0 recorded twice
	CheckpointEntry               githash.Hash // refs/entire/checkpoints/7Z/<ULID>
	RogueEntry                    githash.Hash // refs/heads/rogue, signed by Rogue
	FixedGoodEntry                githash.Hash // refs/heads/fixed, first and valid
	RevokedEntry, RevokeAnnot     githash.Hash // refs/heads/fixed, rogue and skipped
	FixedEntry                    githash.Hash // refs/heads/fixed, the fix back to the good state
}

// CheckpointRef returns the git-refs backend ref for a checkpoint ID.
func CheckpointRef(id string) string {
	return "refs/entire/checkpoints/" + id[len(id)-2:] + "/" + id
}

func pushedBy(pusher string, extra ...string) rsl.CustomFields {
	fields := rsl.CustomFields{
		"custom.entire.io/repository": RepositoryID,
		"custom.entire.io/pusher":     pusher,
	}
	for i := 0; i+1 < len(extra); i += 2 {
		fields[extra[i]] = extra[i+1]
	}
	return fields
}

// NewScenario builds the Scenario repository.
func NewScenario(t *testing.T) *Scenario {
	t.Helper()

	s := &Scenario{Repo: NewRepo(t)}
	s.Bootstrap()

	s.MainFirst = s.Commit("refs/heads/main", "first")
	s.MainFirstEntry = s.Record(s.Cluster, "refs/heads/main", pushedBy(PusherJane))
	s.MainSecond = s.Commit("refs/heads/main", "second")
	s.Record(s.Cluster, "refs/heads/main", pushedBy(PusherJane))

	s.Commit("refs/heads/feature", "feature work")
	s.FeatureEntry = s.Record(s.Cluster, "refs/heads/feature", rsl.CustomFields{
		"custom.entire.io/repository": RepositoryID,
		"custom.entire.io/actor":      "entire-mirror-service",
	})

	s.SetRef("refs/tags/v1.0.0", s.MainFirst)
	s.TagFirstEntry = s.Record(s.Cluster, "refs/tags/v1.0.0", pushedBy(PusherJane, "custom.entire.io/force-push", "true"))
	s.SetRef("refs/tags/v1.0.0", s.MainSecond)
	s.TagMovedEntry = s.Record(s.Cluster, "refs/tags/v1.0.0", pushedBy(PusherJane, "custom.entire.io/force-push", "true"))

	s.Commit(CheckpointRef(CheckpointULID), "checkpoint "+CheckpointULID)
	s.CheckpointEntry = s.Record(s.Cluster, CheckpointRef(CheckpointULID), pushedBy(PusherJane))

	s.TrailerCommit = s.Commit("refs/heads/main", "third\n\nEntire-Checkpoint: "+CheckpointULID)
	s.MainLastEntry = s.Record(s.Cluster, "refs/heads/main", pushedBy(PusherJane))

	s.Commit("refs/heads/rogue", "rogue work")
	s.RogueEntry = s.Record(s.Rogue, "refs/heads/rogue", pushedBy(PusherJane))

	// gittuf recovers from a skipped violation by finding a later entry that
	// is tree-same with the last good one (internal/policy/verify.go), so the
	// fix resets the branch to the good commit.
	good := s.Commit("refs/heads/fixed", "good work")
	s.FixedGoodEntry = s.Record(s.Cluster, "refs/heads/fixed", pushedBy(PusherBob))
	s.Commit("refs/heads/fixed", "rogue work")
	s.RevokedEntry = s.Record(s.Rogue, "refs/heads/fixed", nil)
	s.RevokeAnnot = s.Annotate(s.Cluster, true, "revoked: signed by an unknown key", s.RevokedEntry)
	s.SetRef("refs/heads/fixed", good)
	s.FixedEntry = s.Record(s.Cluster, "refs/heads/fixed", pushedBy(PusherBob))

	return s
}
